"""Additive automation definitions, evidence, queues and rule episodes."""
from sqlalchemy import Table, Column, String, Text, Float, Integer, Boolean, JSON, ForeignKey, UniqueConstraint


def register(meta):
    specs = {
        'automations': [Column('id', String, primary_key=True), Column('name', Text, nullable=False), Column('instructions', Text), Column('revision_id', String), Column('paused', Boolean, default=False), Column('archived_at', Float), Column('created_at', Float), Column('updated_at', Float), Column('next_due', Float, default=0)],
        'automation_revisions': [Column('id', String, primary_key=True), Column('automation_id', ForeignKey('automations.id'), index=True), Column('number', Integer), Column('plan', JSON, nullable=False), Column('created_at', Float), UniqueConstraint('automation_id', 'number')],
        'automation_drafts': [Column('id', String, primary_key=True), Column('instructions', Text), Column('plan', JSON), Column('status', String), Column('questions', JSON), Column('created_at', Float), Column('activated_id', String), Column('monitor_draft_id', String)],
        'automation_dependencies': [Column('revision_id', ForeignKey('automation_revisions.id'), primary_key=True), Column('input_id', String, primary_key=True), Column('monitor_id', String, index=True), Column('field_id', String), Column('source_id', String, index=True), Column('signature', String)],
        'automation_evaluations': [Column('id', String, primary_key=True), Column('automation_id', ForeignKey('automations.id'), index=True), Column('revision_id', ForeignKey('automation_revisions.id'), index=True), Column('job_id', String, unique=True), Column('at', Float, index=True), Column('status', String), Column('error', Text), Column('inputs', JSON), Column('outputs', JSON), Column('conditions', JSON), Column('history', JSON)],
        'automation_current': [Column('automation_id', ForeignKey('automations.id'), primary_key=True), Column('evaluation_id', String), Column('valid_evaluation_id', String), Column('status', String), Column('error', Text), Column('at', Float)],
        'automation_values': [Column('evaluation_id', ForeignKey('automation_evaluations.id'), primary_key=True), Column('field_id', String, primary_key=True), Column('automation_id', String, index=True), Column('revision_id', String), Column('at', Float, index=True), Column('status', String), Column('error', Text), Column('value', JSON), Column('number', Float), Column('unit', Text), Column('period', Text)],
        'automation_rule_states': [Column('revision_id', ForeignKey('automation_revisions.id'), primary_key=True), Column('rule_id', String, primary_key=True), Column('last_condition', Boolean), Column('true_since', Float), Column('notified', Boolean, default=False), Column('last_notified_at', Float), Column('episode', Integer, default=0), Column('alert_id', String)],
        'automation_alerts': [Column('id', String, primary_key=True), Column('automation_id', ForeignKey('automations.id'), index=True), Column('revision_id', String), Column('rule_id', String), Column('evaluation_id', ForeignKey('automation_evaluations.id')), Column('name', Text), Column('kind', String), Column('status', String), Column('at', Float, index=True), Column('acknowledged_at', Float), Column('resolved_at', Float)],
        'automation_jobs': [Column('id', String, primary_key=True), Column('automation_id', ForeignKey('automations.id'), index=True), Column('revision_id', String), Column('reason', String), Column('status', String, index=True), Column('attempts', Integer, default=0), Column('owner', String), Column('generation', Integer, default=0), Column('lease_until', Float, default=0), Column('available_at', Float, default=0), Column('created_at', Float), Column('finished_at', Float), Column('error', Text)],
        'automation_deliveries': [Column('id', String, primary_key=True), Column('alert_id', ForeignKey('automation_alerts.id'), index=True), Column('automation_id', String), Column('revision_id', String), Column('connection_id', String), Column('payload', JSON), Column('status', String, index=True), Column('attempts', Integer, default=0), Column('owner', String), Column('generation', Integer, default=0), Column('lease_until', Float, default=0), Column('available_at', Float, default=0), Column('created_at', Float), Column('finished_at', Float), Column('error', Text), Column('http_status', Integer), UniqueConstraint('alert_id', 'connection_id')],
    }
    result = {name: meta.tables[name] if name in meta.tables else Table(name, meta, *columns) for name, columns in specs.items()}
    globals().update(result)
    globals()['deliveries'] = result['automation_deliveries']
    return result
